import { Injectable, signal } from '@angular/core';
import { APP_CONFIG } from '../config';
import { AyahRef } from '../models';

/**
 * Shape of `content/<edition>/latin.json`, generated by scripts/build-content.mjs
 * (never hand-edited). Keys are "surah:ayah".
 */
export interface LatinFile {
  format: 'mushaf-latin';
  version: 1;
  source: { name: string; url: string; origin: string; license: string; fetchedAt: string };
  ayahs: Record<string, string>;
}

/**
 * Indonesian Latin transliteration (Pedoman Transliterasi Kemenag RI) per ayah.
 * Loaded lazily on first use (~1 MB) and kept in memory; the service worker
 * caches the file so it also works offline once fetched.
 */
@Injectable({ providedIn: 'root' })
export class LatinService {
  private file: Promise<LatinFile | null> | null = null;
  /** Source/attribution once loaded, for display next to the text. */
  readonly source = signal<LatinFile['source'] | null>(null);

  /** Resolves to the transliteration, or null when unavailable (offline before first load, missing file). */
  async get(ref: AyahRef): Promise<string | null> {
    const f = await this.load();
    return f?.ayahs[`${ref.surah}:${ref.ayah}`] ?? null;
  }

  private load(): Promise<LatinFile | null> {
    this.file ??= fetch(`${APP_CONFIG.contentBase}/${APP_CONFIG.editionId}/latin.json`)
      .then(async (r) => {
        if (!r.ok) throw new Error(String(r.status));
        const f = (await r.json()) as LatinFile;
        if (f.format !== 'mushaf-latin' || typeof f.ayahs !== 'object') throw new Error('format');
        this.source.set(f.source);
        return f;
      })
      .catch(() => {
        this.file = null; // retry on the next request (e.g. after coming back online)
        return null;
      });
    return this.file;
  }
}
